/**
  * @brief GPIO Initialization Function
  * @param None
  * @retval None
  */
static void MX_GPIO_Init(void)
{
  GPIO_InitTypeDef GPIO_InitStruct = {0};
  /* USER CODE BEGIN MX_GPIO_Init_1 */

  /* USER CODE END MX_GPIO_Init_1 */

  /* GPIO Ports Clock Enable */
  __HAL_RCC_GPIOH_CLK_ENABLE();
  __HAL_RCC_GPIOA_CLK_ENABLE();
  __HAL_RCC_GPIOB_CLK_ENABLE();

  // -------------------------------
  // LCD pins configuration
  // -------------------------------
  // Configure PC14 (RS) and PC15 (E) as output push-pull
  GPIO_InitStruct.Pin = GPIO_PIN_14 | GPIO_PIN_15;
  GPIO_InitStruct.Mode = GPIO_MODE_OUTPUT_PP;
  GPIO_InitStruct.Pull = GPIO_NOPULL;
  GPIO_InitStruct.Speed = GPIO_SPEED_FREQ_LOW;
  HAL_GPIO_Init(GPIOC, &GPIO_InitStruct);

  // Configure PB8 (D4) and PB9 (D5) as output push-pull
  GPIO_InitStruct.Pin = GPIO_PIN_8 | GPIO_PIN_9;
  HAL_GPIO_Init(GPIOB, &GPIO_InitStruct);

  // Configure PA12 (D6) and PA15 (D7) as output push-pull
  GPIO_InitStruct.Pin = GPIO_PIN_12 | GPIO_PIN_15;
  HAL_GPIO_Init(GPIOA, &GPIO_InitStruct);

  // Set all LCD pins LOW initially
  HAL_GPIO_WritePin(GPIOC, GPIO_PIN_14 | GPIO_PIN_15, GPIO_PIN_RESET);
  HAL_GPIO_WritePin(GPIOB, GPIO_PIN_8 | GPIO_PIN_9, GPIO_PIN_RESET);
  HAL_GPIO_WritePin(GPIOA, GPIO_PIN_12 | GPIO_PIN_15, GPIO_PIN_RESET);


  // -------------------------------
  // Button0 configuration (PA0)
  // -------------------------------
  GPIO_InitStruct.Pin = Button0_Pin;
  GPIO_InitStruct.Mode = GPIO_MODE_IT_RISING; // Interrupt on rising edge
  GPIO_InitStruct.Pull = GPIO_PULLUP;         // Use pull-up resistor
  HAL_GPIO_Init(GPIOA, &GPIO_InitStruct);

  // Enable and set EXTI line 0 interrupt priority
  HAL_NVIC_SetPriority(EXTI0_IRQn, 2, 0);
  HAL_NVIC_EnableIRQ(EXTI0_IRQn);

  /* USER CODE END MX_GPIO_Init_2 */
}

/* USER CODE BEGIN 4 */
void EXTI0_IRQHandler(void){

	// TODO: Debounce using HAL_GetTick()
	static uint32_t last_time = 0;
	uint32_t now = HAL_GetTick();
	if ((now - last_time) > 200) {
	    last_time = now;

		// TODO: Disable DMA transfer and abort IT, then start DMA in IT mode with new LUT and re-enable transfer
		// HINT: Consider using C's "switch" function to handle LUT changes
	    __HAL_TIM_DISABLE_DMA(&htim2,TIM_DMA_CC1);
		HAL_DMA_Abort(&hdma_tim2_ch1);
		switch (waveform_count) {
		case 0:
			lcd_command(CLEAR);
			lcd_putstring("Sine");
			current_lut =  (Sin_LUT); //write Sine LUT address to destination address
			current_lut_size = 256;
			waveform_count++; //update waveform counter
			#define NS 256
			TIM2_Ticks = (uint32_t) (TIM2CLK / (1000));
			break;
		case 1:
			lcd_command(CLEAR);
			lcd_putstring("Saw");
			current_lut =  (Saw_LUT); //write Sine LUT address to destination address
			current_lut_size = 256;
			waveform_count++; //update waveform counter
			#define NS 256
			TIM2_Ticks = (uint32_t) (TIM2CLK / (1000));
			break;
		case 2:
			lcd_command(CLEAR);
			lcd_putstring("Triangle");
			current_lut =  (Triangle_LUT); //write Sine LUT address to destination address
			current_lut_size = 256;
			#define NS 256
			waveform_count++; //update waveform counter
			TIM2_Ticks = (uint32_t) (TIM2CLK / (1000));
			break;
		case 3:
			lcd_command(CLEAR);
			lcd_putstring("Piano");
			current_lut =  (LUT_PIANO); //write Sine LUT address to destination address
			current_lut_size = 25148;

			waveform_count++; //update waveform counter
			TIM2_Ticks = (uint32_t) (TIM2CLK / (4000)); //Fsignal = 4000
			break;
		case 4:
			lcd_command(CLEAR);
			lcd_putstring("Guitar");
			current_lut =  (LUT_GUITAR); //write Sine LUT address to destination address
			current_lut_size = 14107;
			waveform_count++; //update waveform counter

			TIM2_Ticks = (uint32_t) (TIM2CLK / (4000)); //Fsignal = 4000
			break;
		case 5:
			lcd_command(CLEAR);
			lcd_putstring("Drum");
			current_lut = (LUT_DRUM); //write Sine LUT address to destination address
			current_lut_size = 15117;

			waveform_count = 0; //update waveform counter
			TIM2_Ticks = (uint32_t) (TIM2CLK / (4000)); //Fsignal = 4000
			break;
		}


		HAL_TIM_OC_Stop(&htim2, TIM_CHANNEL_1);
		MX_TIM2_Init();
		HAL_TIM_OC_Start_IT(&htim2, TIM_CHANNEL_1);

		HAL_DMA_Start_IT(
		          &hdma_tim2_ch1,
		          (uint32_t)current_lut,
		          DestAddress,
		          current_lut_size
		      );

		__HAL_TIM_ENABLE_DMA(&htim2, TIM_DMA_CC1);
	}

	HAL_GPIO_EXTI_IRQHandler(Button0_Pin); // Clear interrupt flags
}
